import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
/** The SQLite schema is the single source of model definitions for both deployments. */
export function postgresSchema(source: string) {
  return (
    "// Generated by scripts/prepare-postgres.ts; do not edit models here.\n" +
    source
      .replace(
        'provider = "prisma-client-js"',
        'provider = "prisma-client-js"\n  output = "../../node_modules/.prisma/client"',
      )
      .replace('provider = "sqlite"', 'provider = "postgresql"')
      .replace(
        /url\s*= env\("DATABASE_URL"\)/,
        'url = env("DATABASE_URL")\n  directUrl = env("DIRECT_DATABASE_URL")',
      )
  );
}
if (process.argv[1]?.endsWith("prepare-postgres.ts")) {
  mkdirSync("prisma/postgresql", { recursive: true });
  writeFileSync(
    "prisma/postgresql/schema.prisma",
    postgresSchema(readFileSync("prisma/schema.prisma", "utf8")),
  );
  console.log("PostgreSQL schema generated from the local model definitions");
}
